def prison_cells_after_days(cells, n):
 seen={};state=tuple(cells)
 while n:
  if state in seen:
   cycle=seen[state]-n;n%=cycle
  seen[state]=n
  if n:n-=1;state=(0,)+tuple(int(state[i-1]==state[i+1]) for i in range(1,7))+(0,)
 return list(state)

